create or replace function public.get_developer_guard_slot_offer_rc1(p_guard_id uuid)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$
declare v_guard public.guards;v_slot public.job_guard_slots;v_job public.marketplace_jobs;v_property public.properties;v_client public.clients;
begin
 if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501';end if;
 select * into v_guard from public.guards where id=p_guard_id;if v_guard.id is null then raise exception 'GUARD_NOT_FOUND' using errcode='40400';end if;
 select s.* into v_slot from public.job_guard_slots s join public.marketplace_jobs j on j.id=s.job_id where s.guard_id=p_guard_id and s.status in('offered','accepted','en_route','arrived','active') and coalesce(j.pricing_snapshot->>'developer_test','false')='true' order by s.updated_at desc limit 1;
 if v_slot.id is null then return null;end if;
 select * into v_job from public.marketplace_jobs where id=v_slot.job_id;select * into v_property from public.properties where id=v_job.property_id;select * into v_client from public.clients where id=v_job.client_id;
 return jsonb_build_object('assignment_id',v_slot.id,'slot_number',v_slot.slot_number,'required_guards',v_job.required_guards,'job_id',v_job.id,'agency_id',v_slot.agency_id,'guard_id',v_guard.id,'status',v_slot.status,'assigned_at',v_slot.created_at,'offered_at',v_slot.offered_at,'accepted_at',v_slot.accepted_at,'declined_at',v_slot.declined_at,'title',v_job.title,'instructions',v_job.instructions,'priority',v_job.priority,'scheduled_for',v_job.scheduled_for,'duration_minutes',v_job.duration_minutes,'property',jsonb_build_object('name',v_property.name,'address',coalesce(v_property.formatted_address,v_property.address),'latitude',v_property.latitude,'longitude',v_property.longitude,'photo_url',v_property.photo_url),'client',jsonb_build_object('display_name',v_client.display_name),'guard',jsonb_build_object('id',v_guard.id,'user_id',v_guard.user_id,'name',coalesce((select full_name from public.profiles where id=v_guard.user_id),'Guard'),'badge_number',v_guard.badge_number,'availability',v_guard.availability),'multi_guard_slot',true);
end $$;
revoke all on function public.get_developer_guard_slot_offer_rc1(uuid) from public,anon;grant execute on function public.get_developer_guard_slot_offer_rc1(uuid) to authenticated,service_role;

create or replace function public.get_developer_guard_slot_runtime_rc1(p_guard_id uuid,p_job_id uuid)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_slot uuid;begin
 if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501';end if;
 if coalesce((select pricing_snapshot->>'developer_test' from public.marketplace_jobs where id=p_job_id),'false')<>'true' then raise exception 'DEVELOPER_TEST_JOB_REQUIRED';end if;
 select id into v_slot from public.job_guard_slots where job_id=p_job_id and guard_id=p_guard_id;if v_slot is null then raise exception 'STAFFING_SLOT_NOT_OWNED_BY_SELECTED_GUARD' using errcode='42501';end if;
 return (select to_jsonb(s) from public.guard_slot_mission_state s where s.slot_id=v_slot);
end $$;
revoke all on function public.get_developer_guard_slot_runtime_rc1(uuid,uuid) from public,anon;grant execute on function public.get_developer_guard_slot_runtime_rc1(uuid,uuid) to authenticated,service_role;

create or replace function public.transition_developer_guard_slot_mission_rc1(p_guard_id uuid,p_job_id uuid,p_action text,p_expected_version bigint default null,p_checkpoint integer default null,p_evidence jsonb default null,p_incidents jsonb default null)
returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$
declare v_slot public.job_guard_slots;v_state public.guard_slot_mission_state;v_now timestamptz:=now();v_event text;v_record jsonb;v_photos integer:=0;v_drafts integer:=0;v_required integer;v_done integer;
begin
 if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501';end if;
 if coalesce((select pricing_snapshot->>'developer_test' from public.marketplace_jobs where id=p_job_id),'false')<>'true' then raise exception 'DEVELOPER_TEST_JOB_REQUIRED';end if;
 select * into v_slot from public.job_guard_slots where job_id=p_job_id and guard_id=p_guard_id for update;if v_slot.id is null then raise exception 'STAFFING_SLOT_NOT_OWNED_BY_SELECTED_GUARD' using errcode='42501';end if;
 if p_action='accept' then if v_slot.status='accepted' then return coalesce((select to_jsonb(s) from public.guard_slot_mission_state s where s.slot_id=v_slot.id),jsonb_build_object('state','accepted'));end if;if v_slot.status<>'offered' then raise exception 'STAFFING_SLOT_NOT_OFFERED_TO_SELECTED_GUARD';end if;update public.job_guard_slots set status='accepted',accepted_at=v_now,updated_at=v_now where id=v_slot.id;insert into public.guard_slot_mission_state(slot_id,job_id,agency_id,guard_id,state,mission_started_at) values(v_slot.id,p_job_id,v_slot.agency_id,p_guard_id,'accepted',v_now) on conflict(slot_id) do update set state='accepted',mission_started_at=coalesce(guard_slot_mission_state.mission_started_at,v_now),version=guard_slot_mission_state.version+1,updated_at=v_now;update public.guards set availability='on_mission' where id=p_guard_id;v_event:='guard_staffing_slot_accepted';
 elsif p_action='decline' then if v_slot.status<>'offered' then raise exception 'STAFFING_SLOT_NOT_OFFERED_TO_SELECTED_GUARD';end if;update public.job_guard_slots set guard_id=null,status='awaiting_guard',declined_at=v_now,offered_at=null,updated_at=v_now where id=v_slot.id;delete from public.guard_slot_mission_state where slot_id=v_slot.id;update public.guards set availability='available' where id=p_guard_id;insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),'guard_staffing_slot_declined',jsonb_build_object('guard_id',p_guard_id,'slot_number',v_slot.slot_number,'developer_test',true));return jsonb_build_object('success',true,'job_id',p_job_id,'slot_number',v_slot.slot_number,'status','awaiting_guard');
 else
  select * into v_state from public.guard_slot_mission_state where slot_id=v_slot.id for update;if v_state.slot_id is null then raise exception 'GUARD_SLOT_RUNTIME_NOT_STARTED';end if;if p_expected_version is not null and v_state.version<>p_expected_version then raise exception 'MISSION_STATE_CONFLICT';end if;
  if p_action='start_route' then if v_state.state<>'accepted' then raise exception 'ILLEGAL_MISSION_TRANSITION';end if;update public.job_guard_slots set status='en_route',route_started_at=v_now,updated_at=v_now where id=v_slot.id;update public.guard_slot_mission_state set state='en_route',route_started_at=v_now,version=version+1,updated_at=v_now where slot_id=v_slot.id returning * into v_state;v_event:='guard_slot_route_started';
  elsif p_action='mark_arrived' then if v_state.state<>'en_route' then raise exception 'ILLEGAL_MISSION_TRANSITION';end if;update public.job_guard_slots set status='active',arrived_at=v_now,updated_at=v_now where id=v_slot.id;update public.guard_slot_mission_state set state='active',arrived_at=v_now,checkpoint_index=0,version=version+1,updated_at=v_now where slot_id=v_slot.id returning * into v_state;v_event:='guard_slot_arrived';
  elsif p_action='save_payload' then if v_state.state not in('active','checkpoint','review') then raise exception 'MISSION_NOT_ACCEPTING_EXECUTION_UPDATES';end if;update public.guard_slot_mission_state set evidence=coalesce(p_evidence,evidence),incidents=coalesce(p_incidents,incidents),version=version+1,updated_at=v_now where slot_id=v_slot.id returning * into v_state;v_event:='guard_slot_payload_saved';
  elsif p_action='complete_checkpoint' then if v_state.state not in('active','checkpoint') or p_checkpoint is null or p_checkpoint<>v_state.checkpoint_index or p_checkpoint<0 or p_checkpoint>5 then raise exception 'CHECKPOINT_STATE_CONFLICT';end if;if p_evidence is not null then v_state.evidence:=p_evidence;end if;if p_incidents is not null then v_state.incidents:=p_incidents;end if;select item into v_record from jsonb_array_elements(coalesce(v_state.evidence,'[]')) item where (item->>'checkpoint')::integer=p_checkpoint limit 1;v_photos:=coalesce((v_record->>'photos')::integer,0);if p_checkpoint in(2,4) and v_photos<1 then raise exception 'REQUIRED_PHOTO_MISSING';end if;if p_checkpoint in(2,4) and not exists(select 1 from public.mission_evidence_media m where m.job_id=p_job_id and m.guard_id=p_guard_id and m.checkpoint_index=p_checkpoint and m.kind='photo') then raise exception 'REQUIRED_REAL_PHOTO_MISSING';end if;select count(*) into v_drafts from jsonb_array_elements(coalesce(v_state.incidents,'[]')) item where coalesce((item->>'checkpoint')::integer,-1)=p_checkpoint and item->>'status'='draft';if v_drafts>0 then raise exception 'INCIDENT_DRAFT_PENDING';end if;update public.guard_slot_mission_state set state=case when p_checkpoint=5 then 'review' else 'checkpoint' end,checkpoint_index=p_checkpoint+1,evidence=coalesce(p_evidence,evidence),incidents=coalesce(p_incidents,incidents),version=version+1,updated_at=v_now where slot_id=v_slot.id returning * into v_state;v_event:='guard_slot_checkpoint_completed';
  elsif p_action='submit' then if v_state.state<>'review' or v_state.checkpoint_index<>6 then raise exception 'MISSION_NOT_READY_FOR_SUBMISSION';end if;select count(*) into v_drafts from jsonb_array_elements(coalesce(p_incidents,v_state.incidents,'[]')) item where item->>'status'='draft';if v_drafts>0 then raise exception 'INCIDENT_DRAFT_PENDING';end if;update public.guard_slot_mission_state set state='completed',evidence=coalesce(p_evidence,evidence),incidents=coalesce(p_incidents,incidents),completed_at=v_now,version=version+1,updated_at=v_now where slot_id=v_slot.id returning * into v_state;update public.job_guard_slots set status='completed',completed_at=v_now,updated_at=v_now where id=v_slot.id;select greatest(1,coalesce(required_guards,1)) into v_required from public.marketplace_jobs where id=p_job_id;select count(*) into v_done from public.job_guard_slots where job_id=p_job_id and status='completed';if v_done>=v_required then update public.marketplace_jobs set status='completed',updated_at=v_now where id=p_job_id;perform public.ensure_multi_guard_mission_report_rc1(p_job_id);end if;v_event:='guard_slot_completed';
  else raise exception 'UNKNOWN_MISSION_ACTION';end if;
 end if;
 if p_action='accept' then select * into v_state from public.guard_slot_mission_state where slot_id=v_slot.id;end if;
 insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),v_event,jsonb_build_object('slot_number',v_slot.slot_number,'guard_id',p_guard_id,'state',v_state.state,'checkpoint_index',v_state.checkpoint_index,'version',v_state.version,'developer_test',true));return to_jsonb(v_state);
end $$;
revoke all on function public.transition_developer_guard_slot_mission_rc1(uuid,uuid,text,bigint,integer,jsonb,jsonb) from public,anon;grant execute on function public.transition_developer_guard_slot_mission_rc1(uuid,uuid,text,bigint,integer,jsonb,jsonb) to authenticated,service_role;
